int first(int limit, int offset) {
    int total = 0;
    for (int index = 0; index < limit; ++index) {
        if (index % 3 == 0) {
            total += index * 2;
        } else if (index % 3 == 1) {
            total -= index;
        } else {
            total += 7;
        }
        if (total > 1000) {
            total = total / 2;
        }
    }
    return total + offset;
}

